using System;
using System.Collections.Generic;
using System.Linq;
using UnityEngine;
namespace CampaignDemo {
 // Small baked map symbols only; these houses have no collision, ownership or simulation cost.
 public sealed class SettlementClusterInk {
  public sealed class House {public Vector2 point;public float width,height,angle;public int shape;public float Radius {get{return new Vector2(width,height).magnitude*.5f+.035f;}}}
  public readonly List<House> houses=new List<House>();
  public int ClusterCount {get;private set;}public int CityAnchors {get;private set;}public int ResourceAnchors {get;private set;}
  readonly FreeMarchMapRuntime terrain;readonly RoadMapRuntime roads;readonly RecoveryPoint[] cities;readonly ResourceSite[] sites;readonly int seed;
  public SettlementClusterInk(FreeMarchMapRuntime terrain,RoadMapRuntime roads,int seed){this.terrain=terrain;this.roads=roads;this.seed=seed;cities=UnityEngine.Object.FindObjectsOfType<RecoveryPoint>().Where(p=>p.gameObject.scene==terrain.gameObject.scene&&p.kind==FacilityKind.RecoveryPoint).OrderBy(p=>p.transform.position.x).ThenBy(p=>p.transform.position.y).ToArray();sites=UnityEngine.Object.FindObjectsOfType<ResourceSite>().Where(p=>p.gameObject.scene==terrain.gameObject.scene).OrderBy(p=>p.transform.position.x).ThenBy(p=>p.transform.position.y).ToArray();}
  static float Next(System.Random r,float lo,float hi){return Mathf.Lerp(lo,hi,(float)r.NextDouble());}
  static Vector2 Rotate(Vector2 p,float a){return new Vector2(p.x*Mathf.Cos(a)-p.y*Mathf.Sin(a),p.x*Mathf.Sin(a)+p.y*Mathf.Cos(a));}
  Vector2 Local(Vector3 p){return terrain.transform.InverseTransformPoint(p);}
  float RoadDistance(Vector2 p,out float angle){float best=float.MaxValue;angle=0;foreach(var edge in roads.definition.connections){var a=Local(roads.transform.TransformPoint(roads.definition.nodes[edge.a]));var b=Local(roads.transform.TransformPoint(roads.definition.nodes[edge.b]));var d=b-a;float distance=Vector2.Distance(p,a+d*Mathf.Clamp01(Vector2.Dot(p-a,d)/Mathf.Max(.000001f,d.sqrMagnitude)));if(distance<best){best=distance;angle=Mathf.Atan2(d.y,d.x);}}return best;}
  bool Safe(Vector2 p){if(!terrain.definition.bounds.Contains(p))return false;Vector2 world=terrain.transform.TransformPoint(p);var kind=terrain.TerrainAt(new RoadPoint(world.x,world.y));if(kind!=TerrainKind.Ground&&kind!=TerrainKind.Grass)return false;if(terrain.waterMap!=null&&terrain.waterMap.IsRawWater(new RoadPoint(world.x,world.y)))return false;float angle;if(RoadDistance(p,out angle)<roads.definition.roadWidth*.5f+.10f)return false;foreach(var city in cities)if(Vector2.Distance(p,Local(city.transform.position))<.65f)return false;foreach(var site in sites){var r=site.Area;r.xMin-=.20f;r.xMax+=.20f;r.yMin-=.20f;r.yMax+=.20f;if(r.Contains(world))return false;}return true;}
  public bool Fits(House h){if(houses.Any(other=>Vector2.Distance(h.point,other.point)<h.Radius+other.Radius))return false;for(int y=-2;y<=2;y++)for(int x=-2;x<=2;x++)if(!Safe(h.point+Rotate(new Vector2(h.width*x/4,h.height*y/4),h.angle)))return false;return true;}
  List<House> Plan(Vector2 center,float angle,System.Random random){var result=new List<House>();for(int row=-1;row<=1;row++)for(int col=-2;col<=2;col++){if(random.NextDouble()<.17)continue;var h=new House{point=center+Rotate(new Vector2(col*.49f+Next(random,-.025f,.025f),row*.43f+Next(random,-.025f,.025f)),angle),width=Next(random,.20f,.32f),height=Next(random,.15f,.25f),angle=angle+Next(random,-.07f,.07f),shape=(row*5+col+9)%3};if(h.shape==0)h.height=h.width;if(!Fits(h)||result.Any(other=>Vector2.Distance(h.point,other.point)<h.Radius+other.Radius))continue;result.Add(h);}return result;}
  void Anchor(StaffMapCanvas canvas,Vector2 anchor,bool resource){var random=new System.Random(unchecked(seed^Mathf.RoundToInt(anchor.x*100)*397^Mathf.RoundToInt(anchor.y*100)));float angle;RoadDistance(anchor,out angle);int before=houses.Count;int clusters=resource?2:3;for(int group=0;group<clusters;group++){List<House> best=null;for(int attempt=0;attempt<18;attempt++){float bearing=angle+group*Mathf.PI*2/clusters+Next(random,-.70f,.70f);float radius=Next(random,1.5f,2.6f);var center=anchor+new Vector2(Mathf.Cos(bearing),Mathf.Sin(bearing))*radius;var plan=Plan(center,angle+Next(random,-.10f,.10f),random);if(best==null||plan.Count>best.Count)best=plan;if(best.Count>=11)break;}if(best==null||best.Count<4)continue;ClusterCount++;foreach(var house in best){houses.Add(house);Paint(canvas,house);}}if(houses.Count>before){if(resource)ResourceAnchors++;else CityAnchors++;}}
  static void Paint(StaffMapCanvas canvas,House h){var ink=StaffMapStyle.Ink;var fill=StaffMapStyle.Hex(0x646052);float w=h.width*.5f,t=h.height*.5f;var outline=new List<Vector2>();if(h.shape==2){float arm=Mathf.Min(h.width,h.height)*.44f;canvas.Rectangle(h.point+Rotate(new Vector2(0,-t+arm*.5f),h.angle),new Vector2(w,arm*.5f),h.angle,fill,.72f);canvas.Rectangle(h.point+Rotate(new Vector2(-w+arm*.5f,arm*.5f),h.angle),new Vector2(arm*.5f,t-arm*.5f),h.angle,fill,.72f);outline.AddRange(new[]{new Vector2(-w,-t),new Vector2(w,-t),new Vector2(w,-t+arm),new Vector2(-w+arm,-t+arm),new Vector2(-w+arm,t),new Vector2(-w,t)});}else{canvas.Rectangle(h.point,new Vector2(w,t),h.angle,fill,.72f);outline.AddRange(new[]{new Vector2(-w,-t),new Vector2(w,-t),new Vector2(w,t),new Vector2(-w,t)});}for(int i=0;i<outline.Count;i++)outline[i]=h.point+Rotate(outline[i],h.angle);canvas.Polyline(outline,.016f,ink,.80f,true);}
  public void Draw(StaffMapCanvas canvas){foreach(var city in cities)Anchor(canvas,Local(city.transform.position),false);foreach(var site in sites)Anchor(canvas,Local(site.transform.position),true);}
 }
}
